t.script:
        var emp   = null;
        var gps   = null;
        var timer = null;

        var searchBox = document.getElementById('searchBox');
        var empList   = document.getElementById('empList');
        var empCard   = document.getElementById('empCard');
        var ecName    = document.getElementById('ecName');
        var ecStatus  = document.getElementById('ecStatus');
        var ciRow     = document.getElementById('ciRow');
        var ciVal     = document.getElementById('ciVal');
        var gpsRow    = document.getElementById('gpsRow');
        var btnIn     = document.getElementById('btnIn');
        var btnOut    = document.getElementById('btnOut');
        var result    = document.getElementById('result');
        var rIcon     = document.getElementById('rIcon');
        var rMsg      = document.getElementById('rMsg');
        var rRows     = document.getElementById('rRows');
        var mapsBtn   = document.getElementById('mapsBtn');
        var resetBtn  = document.getElementById('resetBtn');

        // ── Search ──────────────────────────────────────────
        searchBox.addEventListener('input', function() {
          clearTimeout(timer);
          var q = this.value.trim();
          if (q.length < 2) { empList.style.display='none'; return; }
          timer = setTimeout(function() { doSearch(q); }, 300);
        });

        document.addEventListener('click', function(e) {
          if (!e.target.closest('.search-wrap')) { empList.style.display='none'; }
        });

        function doSearch(q) {
          ajax('/drivers/attendance/search', {query: q}, function(res) {
            empList.innerHTML = '';
            if (!res.employees || !res.employees.length) {
              var d = document.createElement('div');
              d.className   = 'emp-item';
              d.textContent = 'لا توجد نتائج';
              empList.appendChild(d);
            } else {
              res.employees.forEach(function(e) {
                var d    = document.createElement('div');
                d.className = 'emp-item';
                d.setAttribute('data-id',   e.id);
                d.setAttribute('data-name', e.name);
                var n    = document.createElement('div');
                n.className   = 'ei-name';
                n.textContent = e.name;
                var m    = document.createElement('div');
                m.className   = 'ei-meta';
                m.textContent = [e.job, e.department, e.code ? 'كود: ' + e.code : ''].filter(Boolean).join(' · ');
                d.appendChild(n);
                d.appendChild(m);
                d.addEventListener('click', function() {
                  selectEmp(this.getAttribute('data-id'), this.getAttribute('data-name'));
                });
                empList.appendChild(d);
              });
            }
            empList.style.display = 'block';
          });
        }

        // ── Select Employee ──────────────────────────────────
        function selectEmp(id, name) {
          empList.style.display  = 'none';
          searchBox.value        = name;
          searchBox.disabled     = true;
          emp = {id: parseInt(id), name: name};

          // Reset UI
          result.style.display   = 'none';
          mapsBtn.style.display  = 'none';
          btnIn.style.display    = 'none';
          btnOut.style.display   = 'none';
          ciRow.style.display    = 'none';
          gpsRow.className       = 'gps-row';
          gpsRow.textContent     = '📡 جار تحديد الموقع...';

          ecName.textContent     = name;
          ecStatus.textContent   = 'جار التحقق...';
          ecStatus.className     = 'ec-status';
          empCard.style.display  = 'block';
          resetBtn.style.display = 'block';

          ajax('/drivers/attendance/status', {employee_id: emp.id, tz_name: getTz()}, function(res) {
            if (res.error) { ecStatus.textContent = res.error; return; }

            if (res.is_checked_in) {
              ecStatus.textContent = '🟢 مسجّل الحضور';
              ecStatus.className   = 'ec-status in';
              if (res.check_in_full) {
                ciVal.textContent   = res.check_in_full;
                ciRow.style.display = 'flex';
              }
              btnOut.style.display = 'block';
            } else {
              ecStatus.textContent = '🔴 لم يسجّل الحضور';
              ecStatus.className   = 'ec-status out';
              btnIn.style.display  = 'block';
            }
            getGPS();
          });
        }

        // ── GPS ─────────────────────────────────────────────
        function getGPS() {
          if (!navigator.geolocation) {
            gpsRow.className   = 'gps-row err';
            gpsRow.textContent = '⚠️ GPS غير متاح في هذا المتصفح';
            return;
          }
          navigator.geolocation.getCurrentPosition(
            function(pos) {
              gps = {lat: pos.coords.latitude, lng: pos.coords.longitude};
              gpsRow.className   = 'gps-row ok';
              gpsRow.textContent = '📍 ' + gps.lat.toFixed(5) + ', ' + gps.lng.toFixed(5);
            },
            function() {
              gpsRow.className   = 'gps-row err';
              gpsRow.textContent = '⚠️ لا يمكن تحديد الموقع';
            },
            {enableHighAccuracy: true, timeout: 10000}
          );
        }

        // ── Check In / Out ───────────────────────────────────
        btnIn.addEventListener('click',  function() { doAction('checkin');  });
        btnOut.addEventListener('click', function() { doAction('checkout'); });

        function doAction(action) {
          var btn = action === 'checkin' ? btnIn : btnOut;
          btn.disabled    = true;
          btn.innerHTML   = '⌛ جار المعالجة... ';
          result.style.display = 'none';

          var now = new Date();
          var pad = function(n) { return String(n).padStart(2,'0'); };
          var dt  = now.getFullYear()+'-'+pad(now.getMonth()+1)+'-'+pad(now.getDate())+' '+
                    pad(now.getHours())+':'+pad(now.getMinutes())+':'+pad(now.getSeconds());

          ajax('/drivers/attendance/'+action, {
            employee_id    : emp.id,
            latitude       : gps ? gps.lat : null,
            longitude      : gps ? gps.lng : null,
            location_label : gps ? gps.lat.toFixed(7)+','+gps.lng.toFixed(7) : '',
            local_datetime : dt,
            tz_name        : getTz(),
            tz_offset      : -now.getTimezoneOffset()
          }, function(res) {
            btn.disabled = false;
            btn.textContent = action === 'checkin'
              ? '✅ تسجيل الحضور'
              : '🏁 تسجيل الانصراف';

            if (res.error) {
              showResult(false, res.error, null);
              return;
            }

            // Build result rows
            var rows = '';
            rows += makeRow('📅 التاريخ', res.local_date || '');
            rows += makeRow('🕒 الوقت',    res.local_time || '');
            if (res.worked_hours) {
              rows += makeRow('⏱ ساعات العمل',
                '' + res.worked_hours + '');
            }
            if (gps) {
              rows += makeRow('📍 الموقع',
                gps.lat.toFixed(5) + ', ' + gps.lng.toFixed(5));
            }

            var icon = action === 'checkin' ? '🟢' : '🏁';
            var msg  = action === 'checkin'
              ? 'تم تسجيل الحضور بنجاح'
              : 'تم تسجيل الانصراف بنجاح';

            showResult(true, msg, rows, icon);
            btnIn.style.display  = 'none';
            btnOut.style.display = 'none';

            if (gps) {
              mapsBtn.href          = 'https://www.google.com/maps?q='+gps.lat+','+gps.lng;
              mapsBtn.style.display = 'block';
            }
          });
        }

        function makeRow(label, value) {
          return '
'+label+''+value+'';
        }

        function showResult(ok, msg, rows, icon) {
          result.className    = 'result ' + (ok ? 'ok' : 'err');
          rIcon.innerHTML     = icon || (ok ? '✅' : '❌');
          rMsg.textContent    = msg;
          rRows.innerHTML     = rows || '';
          result.style.display = 'block';
        }

        // ── Reset ────────────────────────────────────────────
        resetBtn.addEventListener('click', function() {
          emp = null; gps = null;
          searchBox.value        = '';
          searchBox.disabled     = false;
          empCard.style.display  = 'none';
          btnIn.style.display    = 'none';
          btnOut.style.display   = 'none';
          result.style.display   = 'none';
          mapsBtn.style.display  = 'none';
          resetBtn.style.display = 'none';
          empList.style.display  = 'none';
          searchBox.focus();
        });

        // ── Helpers ──────────────────────────────────────────
        function getTz() {
          try { return Intl.DateTimeFormat().resolvedOptions().timeZone; } catch(e) { return 'UTC'; }
        }

        function ajax(url, params, cb) {
          var xhr = new XMLHttpRequest();
          xhr.open('POST', url, true);
          xhr.setRequestHeader('Content-Type','application/json');
          xhr.onload  = function() {
            try { cb(JSON.parse(xhr.responseText).result || {}); }
            catch(e) { cb({error:'Server error'}); }
          };
          xhr.onerror = function() { cb({error:'Network error'}); };
          xhr.send(JSON.stringify({jsonrpc:'2.0',method:'call',params:params}));
        }

        window.addEventListener('load', function() { searchBox.focus(); });
